            double gamma = 28; // 28 MHz/mT
            double MagnetField_Off_A = (ODMR_freq_currentOff[0] - ODMR_freq_currentOff[7]) / 2 * gamma;
            double MagnetField_Off_B = (ODMR_freq_currentOff[1] - ODMR_freq_currentOff[6]) / 2 * gamma;
            double MagnetField_Off_C = (ODMR_freq_currentOff[2] - ODMR_freq_currentOff[5]) / 2 * gamma;
            double MagnetField_Off_D = (ODMR_freq_currentOff[3] - ODMR_freq_currentOff[4]) / 2 * gamma;

            double MagnetField_On_A = (ODMR_freq_currentOn[0] - ODMR_freq_currentOn[7]) / 2 * gamma;
            double MagnetField_On_B = (ODMR_freq_currentOn[1] - ODMR_freq_currentOn[6]) / 2 * gamma;
