            // Delta_Magnetic field
            double MagnetField_Diff_A = MagnetField_On_A - MagnetField_Off_A;
            double MagnetField_Diff_B = MagnetField_On_B - MagnetField_Off_B;
            double MagnetField_Diff_C = MagnetField_On_C - MagnetField_Off_C;
